/** Fresh bounded verification after a proven zero-write failure. Never resets a prior journal. */
import {open,readFile,unlink} from 'node:fs/promises';
import {runM78Continuation,parseM78ContinuationInput,readM78ContinuationJournal,cleanM78ContinuationJournal,type M78JourneyInput,type M78Dependencies} from './check-m78-continuation';
import {m78CanonicalJson as canonical} from '../../packages/neuvetra-database/src/m78-validation';
export const M78_CONTINUATION3_PATHS={journal:'.superpowers/m78-hosted-continuation3.jsonl',diagnostics:'.superpowers/m78-hosted-continuation3-diagnostics.jsonl',failed:'.superpowers/m78-hosted-continuation.jsonl',interrupted:'.superpowers/m78-hosted-continuation2.jsonl',interruptedDiagnostics:'.superpowers/m78-hosted-continuation2-diagnostics.jsonl',disposition:'.superpowers/m78-continuation3-cleanup-disposition.json',stop:'.superpowers/m78-hosted-continuation3.stop'}as const;
export const M78_CONTINUATION3_INTERRUPTION={mainSha256:'3ce68c3fc87e37623326badb88d412f2db36daceacf43060c5849f287a358507',mainHead:'9762c119f900df7be09426114f49e06c888af3ae3d3fba42dc81a7a00482c25e',diagnosticsSha256:'8ae88cd344ab1a6376b91a63581c57c9c61c381eb57141e1b6a11ca7647eae08',diagnosticsHead:'a7af0d5e04a71cc883b75aaf6921c6bb2de94049f00e3c21427a8736df2dd04e'}as const;
